class JobCollection:
    def __init__(self, jobs):
        self.jobs = jobs # List of Job objects

    def is_normal(self):
        for job_j in self.jobs:
            for pred_id in job_j.predecessors:
                job_pred = self.get_job_by_id(pred_id)
                if job_pred.r != job_j.r or job_pred.d != job_j.d:
                    return False
        return True

# Note: Sporadic DAG task systems inherently generate normal collections.

def schedule_A_infinity(job_collection):
    schedule = {}
    job_completion_times = {}

    # Sort jobs by release time and then by dependencies (topological sort)
    # For simplicity, assume jobs are processed in an order that respects dependencies
    sorted_jobs = topological_sort(job_collection.jobs)

    for job_j in sorted_jobs:
        earliest_start_time = job_j.r
        for pred_id in job_j.predecessors:
            earliest_start_time = max(earliest_start_time, job_completion_times[pred_id])

        job_start_time = earliest_start_time
        job_completion_time = job_start_time + job_j.e # Assuming actual execution time is WCET for analysis
        job_completion_times[job_j.id] = job_completion_time
        schedule[job_j.id] = (job_start_time, job_completion_time)
    return schedule

def calculate_work_J_I(job_sequence_J, interval_I, A_infinity_schedule):
    work_amount = 0
    interval_start, interval_end = interval_I

    for job_j in job_sequence_J.jobs:
        if job_j.d >= interval_start and job_j.d <= interval_end:
            # Get actual execution start and end from A_infinity_schedule
            exec_start, exec_end = A_infinity_schedule.get(job_j.id, (None, None))
            if exec_start is not None:
                # Work done by A_infinity on job_j within interval_I
                work_in_I = max(0, min(exec_end, interval_end) - max(exec_start, interval_start))
                work_amount += work_in_I
    return work_amount

