def calculate_w_hat_i_t(task_i, interval_length_t, epsilon):
    threshold = task_i.T / epsilon + (1 + 1/epsilon) * task_i.D
    if interval_length_t <= threshold:
        # For small t, compute work_i_t exactly (complex, assume function exists)
        return calculate_work_i_t_exact(task_i, interval_length_t)
    else:
        # For large t, use the linear approximation
        return max(0, (interval_length_t - task_i.D) / task_i.T) * task_i.G.vol

