def edf_sufficient_condition_theorem21(task_system_T, m_processors):
    for k, task_k in enumerate(task_system_T.tasks):
        # Condition (i)
        if task_k.G.len > task_k.D / 3:
            return False

        # Condition (ii)
        sum_utilization = 0
        for i, task_i in enumerate(task_system_T.tasks):
            if task_i.T <= task_k.D:
                sum_utilization += task_i.G.vol / task_i.T
            else:
                sum_utilization += task_i.G.vol / task_k.D # Note: D_k here, not D_i

        if sum_utilization > (m_processors + 0.5) / 3:
            return False

    return True

def dm_sufficient_condition_theorem22(task_system_T, m_processors):
    for k, task_k in enumerate(task_system_T.tasks):
        # Condition (i)
        if task_k.G.len > task_k.D / 5:
            return False

        # Condition (ii)
        sum_utilization = 0
        for i, task_i in enumerate(task_system_T.tasks):
            if task_i.T <= 2 * task_k.D:
                sum_utilization += task_i.G.vol / task_i.T
            else:
                sum_utilization += task_i.G.vol / (4 * task_k.D) # Note: 4*D_k here

        if sum_utilization > (m_processors + 0.25) / 5:
            return False

    return True

def dm_sufficient_condition_theorem23(task_system_T, m_processors):
    for k, task_k in enumerate(task_system_T.tasks):
        # Condition (iii)
        if task_k.D > task_k.T:
            return False # This theorem only applies to constrained deadlines

        # Condition (i)
        if task_k.G.len > task_k.D / 4:
            return False

        # Condition (ii)
        sum_utilization = 0
        for i, task_i in enumerate(task_system_T.tasks):
            if task_i.T <= task_k.D:
                sum_utilization += task_i.G.vol / task_i.T
            else:
                sum_utilization += task_i.G.vol / task_k.D # Note: D_k here

        if sum_utilization > (m_processors + 1/3) / 4:
            return False

    return True
